create table if not exists public.production_daily_actuals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),operational_date date not null,process text not null check(process='DTG'),machine_code text not null,garments bigint not null check(garments>=0),prints numeric not null check(prints>=0),source_event_count bigint not null check(source_event_count>=0),source_min_audit_id bigint,source_max_audit_id bigint,source_max_event_at timestamptz,source_system text not null default 'ORACLE_ISIS_AUDIT',calculation_version text not null default 'DTG_PCOR_COMPLETION_V1',refreshed_at timestamptz not null default now(),unique(organization_id,operational_date,process,machine_code));create index if not exists production_daily_actuals_period_idx on public.production_daily_actuals(organization_id,process,operational_date);alter table public.production_daily_actuals enable row level security;create policy production_daily_actuals_read on public.production_daily_actuals for select to authenticated using(public.has_org_role(organization_id,array['viewer','operator','supervisor','maintenance','manager','admin']));revoke all on public.production_daily_actuals from public,anon,authenticated;grant select on public.production_daily_actuals to authenticated;grant all on public.production_daily_actuals to service_role;
create or replace function public.replace_dtg_daily_actuals(p_organization_id uuid,p_from date,p_to date,p_rows jsonb)returns bigint language plpgsql security definer set search_path=public as $$declare v_count bigint;begin if p_from is null or p_to is null or p_from>p_to or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>10000 then raise exception 'INVALID_DTG_DAILY_PAYLOAD';end if;if exists(select 1 from jsonb_array_elements(p_rows)r where (r->>'operationalDate')::date not between p_from and p_to or coalesce(r->>'process','')<>'DTG' or coalesce((r->>'garments')::numeric,-1)<0 or coalesce((r->>'prints')::numeric,-1)<0)then raise exception 'INVALID_DTG_DAILY_ROW';end if;if exists(select 1 from jsonb_array_elements(p_rows)r group by r->>'operationalDate',upper(coalesce(nullif(trim(r->>'machineCode'),''),'UNATTRIBUTED')) having count(*)>1)then raise exception 'DUPLICATE_DTG_DAILY_GRAIN';end if;delete from public.production_daily_actuals where organization_id=p_organization_id and process='DTG' and operational_date between p_from and p_to;insert into public.production_daily_actuals(organization_id,operational_date,process,machine_code,garments,prints,source_event_count,source_min_audit_id,source_max_audit_id,source_max_event_at,source_system,calculation_version,refreshed_at)select p_organization_id,(r->>'operationalDate')::date,'DTG',upper(coalesce(nullif(trim(r->>'machineCode'),''),'UNATTRIBUTED')),(r->>'garments')::bigint,(r->>'prints')::numeric,(r->>'sourceEventCount')::bigint,nullif(r->>'sourceMinAuditId','')::bigint,nullif(r->>'sourceMaxAuditId','')::bigint,nullif(r->>'sourceMaxEventAt','')::timestamptz,'ORACLE_ISIS_AUDIT',coalesce(nullif(r->>'calculationVersion',''),'DTG_PCOR_COMPLETION_V1'),now() from jsonb_array_elements(p_rows)r;get diagnostics v_count=row_count;return v_count;end$$;revoke all on function public.replace_dtg_daily_actuals(uuid,date,date,jsonb) from public,anon,authenticated;grant execute on function public.replace_dtg_daily_actuals(uuid,date,date,jsonb) to service_role;
